export function render(container: HTMLElement) {
  container.innerHTML = '';

  // Board container
  const boardContainer = document.createElement('div');
  boardContainer.className = 'row';
  container.appendChild(boardContainer);

  // Board
  const board = document.createElement('div');
  board.className = 'col';
  board.style.position = 'relative';
  board.style.width = '100%';
  board.style.height = '100%';
  boardContainer.appendChild(board);

  // Board size
  const boardSize = 8;

  // Board squares
  for (let row = 0; row < boardSize; row++) {
    for (let col = 0; col < boardSize; col++) {
      const square = document.createElement('div');
      square.className = 'square';
      square.style.position = 'absolute';
      square.style.width = '100%';
      square.style.height = '100%';
      square.style.left = `${(col / boardSize) * 100}%`;
      square.style.top = `${(row / boardSize) * 100}%`;
      square.style.backgroundColor = (row + col) % 2 === 0 ? '#888888' : '#666666';
      board.appendChild(square);
    }
  }

  // Pieces
  const pieces = [
    { row: 0, col: 0, type: 'rook', color: 'white' },
    { row: 0, col: 1, type: 'knight', color: 'white' },
    { row: 0, col: 2, type: 'bishop', color: 'white' },
    { row: 0, col: 3, type: 'queen', color: 'white' },
    { row: 0, col: 4, type: 'king', color: 'white' },
    { row: 0, col: 5, type: 'bishop', color: 'white' },
    { row: 0, col: 6, type: 'knight', color: 'white' },
    { row: 0, col: 7, type: 'rook', color: 'white' },
    { row: 1, col: 0, type: 'pawn', color: 'white' },
    { row: 1, col: 1, type: 'pawn', color: 'white' },
    { row: 1, col: 2, type: 'pawn', color: 'white' },
    { row: 1, col: 3, type: 'pawn', color: 'white' },
    { row: 1, col: 4, type: 'pawn', color: 'white' },
    { row: 1, col: 5, type: 'pawn', color: 'white' },
    { row: 1, col: 6, type: 'pawn', color: 'white' },
    { row: 1, col: 7, type: 'pawn', color: 'white' },
    { row: 6, col: 0, type: 'pawn', color: 'black' },
    { row: 6, col: 1, type: 'pawn', color: 'black' },
    { row: 6, col: 2, type: 'pawn', color: 'black' },
    { row: 6, col: 3, type: 'pawn', color: 'black' },
    { row: 6, col: 4, type: 'pawn', color: 'black' },
    { row: 6, col: 5, type: 'pawn', color: 'black' },
    { row: 6, col: 6, type: 'pawn', color: 'black' },
    { row: 6, col: 7, type: 'pawn', color: 'black' },
    { row: 7, col: 0, type: 'rook', color: 'black' },
    { row: 7, col: 1, type: 'knight', color: 'black' },
    { row: 7, col: 2, type: 'bishop', color: 'black' },
    { row: 7, col: 3, type: 'queen', color: 'black' },
    { row: 7, col: 4, type: 'king', color: 'black' },
    { row: 7, col: 5, type: 'bishop', color: 'black' },
    { row: 7, col: 6, type: 'knight', color: 'black' },
    { row: 7, col: 7, type: 'rook', color: 'black' },
  ];

  // Render pieces
  for (const piece of pieces) {
    const pieceDiv = document.createElement('div');
    pieceDiv.className = 'piece';
    pieceDiv.style.position = 'absolute';
    pieceDiv.style.left = `${(piece.col / boardSize) * 100}%`;
    pieceDiv.style.top = `${(piece.row / boardSize) * 100}%`;
    pieceDiv.style.backgroundColor = piece.color === 'white' ? '#ffffff' : '#000000';
    board.appendChild(pieceDiv);
  }

  // Rule book button
  const ruleBookButton = document.createElement('button');
  ruleBookButton.className = 'btn';
  ruleBookButton.textContent = 'Rule Book';
  ruleBookButton.onclick = () => {
    alert('Rule Book clicked');
  };
  boardContainer.appendChild(ruleBookButton);

  // New game button
  const newGameButton = document.createElement('button');
  newGameButton.className = 'btn';
  newGameButton.textContent = 'New Game';
  newGameButton.onclick = () => {
    alert('New game clicked');
  };
  boardContainer.appendChild(newGameButton);

  // Undo move button
  const undoMoveButton = document.createElement('button');
  undoMoveButton.className = 'btn';
  undoMoveButton.textContent = 'Undo Move';
  undoMoveButton.onclick = () => {
    alert('Undo move clicked');
  };
  boardContainer.appendChild(undoMoveButton);

  // AI move button
  const aiMoveButton = document.createElement('button');
  aiMoveButton.className = 'btn';
  aiMoveButton.textContent = 'AI Move';
  aiMoveButton.onclick = () => {
    alert('AI move clicked');
  };
  boardContainer.appendChild(aiMoveButton);

  // Score display
  const scoreDisplay = document.createElement('div');
  scoreDisplay.className = 'score';
  scoreDisplay.textContent = 'Score: 0';
  boardContainer.appendChild(scoreDisplay);
}

