export class InputHandler {
  private board: ChessBoard;

  constructor(board: ChessBoard) {
    this.board = board;
  }

  handleInput(input: string): void {
    try {
      const [from, to] = input.split(' ');
      const fromCol = from.charCodeAt(0) - 97;
      const fromRow = parseInt(from[1]) - 1;
      const toCol = to.charCodeAt(0) - 97;
      const toRow = parseInt(to[1]) - 1;

      if (fromCol < 0 || fromCol > 7 || fromRow < 0 || fromRow > 7 || toCol < 0 || toCol > 7 || toRow < 0 || toRow > 7) {
        console.log('Invalid move: out of bounds');
        return;
      }

      const piece = this.board.getPiece(fromCol, fromRow);
      if (!piece) {
        console.log('Invalid move: no piece at source');
        return;
      }

      if (!this.isValidMove(piece, fromCol, fromRow, toCol, toRow)) {
        console.log('Invalid move: not a valid move for the selected piece');
        return;
      }

      this.board.setPiece(toCol, toRow, piece);
      this.board.setPiece(fromCol, fromRow, null);
    } catch (error) {
      console.error('Error handling input:', error);
    }
  }

  private isValidMove(piece: Piece, fromCol: number, fromRow: number, toCol: number, toRow: number): boolean {
    const isWhiteTurn = true;
    const isValid = true;

    if (piece.color === 'w' && isWhiteTurn) {
      if (piece.type === 'p') {
        if (toCol === fromCol && toRow === fromRow + 1) {
          return true;
        }
        if (toCol === fromCol && toRow === fromRow + 2 && fromRow === 1) {
          return true;
        }
      }
    }

    return isValid;
  }
}

