export class DataStore {
  private data: { [key: string]: any };

  constructor() {
    this.data = {};
  }

  store(key: string, value: any): void {
    this.data[key] = value;
  }

  retrieve(key: string): any {
    return this.data[key];
  }

  delete(key: string): void {
    delete this.data[key];
  }

  getAll(): { [key: string]: any } {
    return this.data;
  }
}

