export class GameEngine {
  private board: string[][];
  private turn: 'white' | 'black';
  private gameOver: boolean;
  private winner: 'white' | 'black' | null;
  private moves: { from: string; to: string }[];

  constructor() {
    this.board = [
      ['r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'],
      ['p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'],
      ['', '', '', '', '', '', '', ''],
      ['', '', '', '', '', '', '', ''],
      ['', '', '', '', '', '', '', ''],
      ['', '', '', '', '', '', '', ''],
      ['P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'],
      ['R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R'],
    ];
    this.turn = 'white';
    this.gameOver = false;
    this.winner = null;
    this.moves = [];
  }

  getBoard(): string[][] {
    return this.board;
  }

  getTurn(): 'white' | 'black' {
    return this.turn;
  }

  getGameOver(): boolean {
    return this.gameOver;
  }

  getWinner(): 'white' | 'black' | null {
    return this.winner;
  }

  getMoves(): { from: string; to: string }[] {
    return this.moves;
  }

  isValidMove(from: string, to: string): boolean {
    if (this.gameOver) return false;
    if (this.board[from[0]][from[1]] === '') return false;
    if (this.board[from[0]][from[1]] === 'K' && Math.abs(from[0] - to[0]) > 2) return false;
    if (Math.abs(from[0] - to[0]) > 1 || Math.abs(from[1] - to[1]) > 1) return false;
    if (this.board[to[0]][to[1]] !== '' && this.board[from[0]][from[1]] === this.board[to[0]][to[1]]) return false;
    return true;
  }

  makeMove(from: string, to: string): void {
    if (!this.isValidMove(from, to)) return;
    this.board[to[0]][to[1]] = this.board[from[0]][from[1]];
    this.board[from[0]][from[1]] = '';
    this.turn = this.turn === 'white' ? 'black' : 'white';
    this.moves.push({ from, to });
    if (this.isCheckmate()) {
      this.gameOver = true;
      this.winner = this.turn;
    }
  }

  isCheckmate(): boolean {
    if (this.gameOver) return false;
    for (let i = 0; i < 8; i++) {
      for (let j = 0; j < 8; j++) {
        if (this.board[i][j] === '') continue;
        for (let k = 0; k < 8; k++) {
          for (let l = 0; l < 8; l++) {
            if (this.board[k][l] !== '' && this.board[i][j] !== this.board[k][l]) {
              if (this.isValidMove({ row: i, col: j }, { row: k, col: l })) return true;
            }
          }
        }
      }
    }
    return false;
  }
}
